package com.elitedarkkaiser.nubialy;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.function.Supplier;
/** Illustrative Settings layout, not live device data. */
public final class SettingsLayoutPreview extends View {
 private final int layout;private final Supplier<SettingsStyle> read;
 public SettingsLayoutPreview(Context c,int layout,Supplier<SettingsStyle> s){super(c);this.layout=layout;read=s;setContentDescription(layout==0?"REDMAGIC Stock Settings preview":"RisingOS Settings preview");}
 @Override protected void onDraw(Canvas c){super.onDraw(c);SettingsStyle s=read.get();int save=c.save();try{c.scale(getWidth()/180f,getHeight()/250f);Paint p=new Paint(3);p.setColor(s.background());c.drawRoundRect(0,0,180,250,20,20,p);p.setColor(s.title());p.setTextSize(14);c.drawText("Settings",14,27,p);if(layout==1){for(int i=0;i<2;i++){p.setColor(s.card());c.drawRoundRect(12+i*81,39,87+i*81,111,12,12,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(s.accent());c.drawArc(30+i*81,51,67+i*81,88,-90,i==0?295:110,false,p);p.setStyle(Paint.Style.FILL);p.setColor(s.summary());p.setTextSize(8);c.drawText(i==0?"Battery":"Storage",25+i*81,102,p);}p.setColor(s.card());c.drawRoundRect(12,119,168,141,9,9,p);p.setColor(s.accent());c.drawCircle(25,130,6,p);}
 int y=layout==1?150:44;for(int i=0;i<(layout==1?3:5);i++){p.setColor(s.card());c.drawRoundRect(12,y,168,y+24,layout==1?9:4,layout==1?9:4,p);p.setColor(s.accent());c.drawCircle(25,y+12,6,p);p.setColor(s.title());c.drawRoundRect(40,y+7,110,y+10,1,1,p);p.setColor(s.summary());c.drawRoundRect(40,y+15,135,y+17,1,1,p);y+=29;}p.setColor(s.card());c.drawRoundRect(12,224,168,241,9,9,p);p.setColor(s.summary());p.setTextSize(8);c.drawText("Search settings",28,235,p);}finally{c.restoreToCount(save);}}
}
